--
-- Name: add_business_day(date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_business_day(from_date date, num_days integer) RETURNS date
    LANGUAGE sql
    AS $$
    select d
    from (
        select d::date, row_number() over (order by d)
        from generate_series(from_date+ 1, from_date+ num_days* 2+ 5, '1d') d
        where 
            extract('dow' from d) not in (0, 6) 
        ) s
    where row_number = num_days
$$;


--
-- Name: aes_cbc_mix_sha256_decrypt(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aes_cbc_mix_sha256_decrypt(data text, key text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  res text;
  dataHex text;
  iv bytea;
  aes_key bytea;
  encrypted_data bytea;
BEGIN
  SELECT decode(key, 'hex') INTO aes_key;
  SELECT encode(decode(data, 'base64'), 'hex') INTO dataHex;
  SELECT decode(SUBSTRING(dataHex FROM 1 FOR 32), 'hex') INTO iv;
  SELECT decode(SUBSTRING(dataHex FROM 33 FOR (SELECT LENGTH(dataHex) - 32 - 64)), 'hex') INTO encrypted_data;
 SELECT decode(SUBSTRING(dataHex FROM 32 FOR (64)), 'hex') INTO encrypted_data;
  SELECT encode(decrypt_iv(encrypted_data, aes_key, iv, 'aes-cbc'), 'escape') INTO res;
  RETURN res;
  
    EXCEPTION WHEN others THEN
        RETURN sqlerrm || encrypted_data||' '|| LENGTH(dataHex) - 32 - 64 ||' '||LENGTH(dataHex);
END;
$$;


