--
-- Name: debtkafka(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.debtkafka(IN log_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
temprow  RECORD;

debt_id bigint;
procname varchar(100) :='debtkafka';
packet varchar(100) := 'Universal.DZ';
begin 


for temprow in  select (data->'value'->>'Debt') as debt, (data->'value'->>'Client') as client,(data->'value'->>'Contract') as contract ,
upsert(data->'value'->>'ContractNumber',data->'value'->>'Contract','its_contract') as contract_id,
to_date((data->'value'->>'DZFormationDate'),'yyyy-mm-dd') as DZFormationDate,(data->'value'->>'City') as city,(data->'value'->>'CityName') as cityname,(data->'value'->>'Zone') as zonename,
(data->'value'->>'PropertyType') as its_premises_type,(data->'value'->>'PropertyTypeName') as its_premises_type_name,(data->'value'->>'Property') as its_premises,(data->'value'->>'PropertyNumber') as its_premises_name,(data->'value'->>'Object') as objectid,(data->'value'->>'ObjectName') as object_name,(data->'value'->>'AccauntNumber') as account_number
from its_kafkalog
where id = log_id loop 	


insert into its_debt(amount,cli_id,contract_id,formation_date,city_id,its_uchastkion_id,its_premises_type_id,its_premises_id,its_real_estate_id,account_number)
select temprow.debt::double precision
 as amount, (select id from its_cli where code=temprow.client) as cli_id ,
  id  as contract_id ,
 temprow.DZFormationDate as formation_date,
 upsert(temprow.cityname,temprow.city,'its_city') as city_id,
 (select id from its_uchastkion where title =temprow.zonename) as its_uchastkion_id,
 upsert(temprow.its_premises_type_name,temprow.its_premises_type,'its_premises_type') as its_premises_type_id,
 upsert(temprow.its_premises_name,temprow.its_premises,'its_premises') as its_premises_id,
 upsert(temprow.object_name,temprow.objectid,'its_real_estate') as its_real_estate_id,
 temprow.account_number as account_number
  
 from its_contract where code = temprow.contract
 on conflict (contract_id,formation_date) do update set amount=excluded.amount,city_id=excluded.city_id,its_uchastkion_id=excluded.its_uchastkion_id,its_premises_type_id=excluded.its_premises_type_id,
its_premises_id=excluded.its_premises_id,its_real_estate_id=excluded.its_real_estate_id,account_number=excluded.account_number;


select d.id into debt_id from its_debt d where contract_id =(select id from its_contract where code = temprow.contract)
and formation_date =temprow.DZFormationDate;

 
insert into its_debt_accruals(its_debt_id,amount,type_id,formation_date)
  select distinct debt_id as its_debt_id,s.accrual ::double precision as amount, (select id from its_accrual_type where code=s.actype) as type_id, to_date(s.acdate ,'yyyy-mm-dd') as formation_date from (
     select  
     ((elements)::jsonb)->>'Debt' as  accrual,
     ((elements)::jsonb)->>'AccrualType' as actype ,
   ((elements)::jsonb)->>'DZFormationDate' as acdate 
from its_kafkalog l
CROSS JOIN lateral jsonb_array_elements(data->'value'->'Accruals') elements
where l.id = log_id) s where s.actype not in ( '00000000-0000-0000-0000-000000000000')
on conflict (its_debt_id,type_id) do update  set amount=excluded.amount;



update its_debt d
set positive_amount =(select coalesce((select sum(amount) from its_debt_accruals where amount>0 and its_debt_id=d.id),0))
where d.id=debt_id;

insert into its_debt_hst(amount,positive_amount,debt_id)
select d.amount ,d.positive_amount , d.id from its_debt d where id= debt_id;


end loop;	

update its_kafkalog set status=2 where id=log_id;

insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where id=log_id;

delete from its_kafkalog  where id=log_id;

end

$$;


--
-- Name: debtkafkamass(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.debtkafkamass(IN log_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
temprow  RECORD;
positive_debt decimal;
debt_id bigint;
procname varchar(100) :='debtkafka';
packet varchar(100) := 'Universal.DZ';
begin 


for temprow in  
select 
(data.elements->>'Debt') as debt,
(data.elements->>'Client') as client,
(data.elements->>'Contract') as contract ,
upsert(data.elements->>'ContractNumber',data.elements->>'Contract','its_contract') as contract_id,
to_date((data.elements->>'DZFormationDate'),'yyyy-mm-dd') as DZFormationDate,
(data.elements->>'City') as city,
(data.elements->>'CityName') as cityname,
(data.elements->>'Zone') as zonename,
(data.elements->>'PropertyType') as its_premises_type,
(data.elements->>'PropertyTypeName') as its_premises_type_name,
(data.elements->>'Property') as its_premises,
(data.elements->>'PropertyNumber') as its_premises_name,
(data.elements->>'Object') as objectid,
(data.elements->>'ObjectName') as object_name,
(data.elements->>'AccauntNumber') as account_number,
(data.elements->'Accruals') as accruals
from (
select elements from its_kafkalog
CROSS JOIN lateral jsonb_array_elements(data->'value') elements 
where id = log_id 
) as data 

loop 	

begin 

select coalesce(sum(s.debt::decimal),0) into positive_debt from (

select distinct jsonb_array_elements(data.elements->'Accruals')->>'Debt' as debt ,
jsonb_array_elements(data.elements->'Accruals')->>'AccrualType' as actype
from (
select elements from its_kafkalog
CROSS JOIN lateral jsonb_array_elements(data->'value') elements 
where id = log_id and elements->>'Contract'=temprow.contract
) as data 
) s
where  s.actype not in ( '00000000-0000-0000-0000-000000000000') and s.debt::decimal  >0;


if positive_debt >0 then 

insert into its_debt(amount,cli_id,contract_id,formation_date,city_id,its_uchastkion_id,its_premises_type_id,its_premises_id,its_real_estate_id,account_number)
select temprow.debt::decimal
 as amount, (select id from its_cli where code=temprow.client) as cli_id ,
  id  as contract_id ,
 temprow.DZFormationDate as formation_date,
 upsert(temprow.cityname,temprow.city,'its_city') as city_id,
 (select id from its_uchastkion where title =temprow.zonename) as its_uchastkion_id,
 upsert(temprow.its_premises_type_name,temprow.its_premises_type,'its_premises_type') as its_premises_type_id,
 upsert(temprow.its_premises_name,temprow.its_premises,'its_premises') as its_premises_id,
 upsert(temprow.object_name,temprow.objectid,'its_real_estate') as its_real_estate_id,
 temprow.account_number as account_number
  
 from its_contract where code = temprow.contract
 on conflict (contract_id,formation_date) do update set amount=excluded.amount,city_id=excluded.city_id,its_uchastkion_id=excluded.its_uchastkion_id,its_premises_type_id=excluded.its_premises_type_id,
its_premises_id=excluded.its_premises_id,its_real_estate_id=excluded.its_real_estate_id,account_number=excluded.account_number;


select d.id into debt_id from its_debt d where contract_id =(select id from its_contract where code = temprow.contract)
and formation_date =temprow.DZFormationDate;

 
insert into its_debt_accruals(its_debt_id,amount,type_id,formation_date)
  select distinct debt_id as its_debt_id,s.accrual ::decimal as amount, 
  (select id from its_accrual_type where code=s.actype) as type_id, 
  to_date(s.acdate ,'yyyy-mm-dd') as formation_date from (
  
  select * from (

select distinct jsonb_array_elements(data.elements->'Accruals')->>'Debt' as accrual ,
jsonb_array_elements(data.elements->'Accruals')->>'AccrualType' as actype,
jsonb_array_elements(data.elements->'Accruals')->>'DZFormationDate' as acdate
from (
select elements from its_kafkalog
CROSS JOIN lateral jsonb_array_elements(data->'value') elements 
where id = log_id and elements->>'Contract'=temprow.contract
) as data 
) s
where  s.actype not in ( '00000000-0000-0000-0000-000000000000') ) s
  
on conflict (its_debt_id,type_id) do update  set amount=excluded.amount;

update its_debt d
set positive_amount =positive_debt
where d.id=debt_id;

insert into its_debt_hst(amount,positive_amount,debt_id)
select d.amount ,d.positive_amount , d.id from its_debt d where id= debt_id;

else

update its_debt d
set positive_amount =positive_debt,
amount = temprow.debt::decimal
where d.id in (select d.id  from its_debt d where contract_id in (select id from its_contract where code = temprow.contract));

insert into its_debt_hst(amount,positive_amount,debt_id)
select d.amount ,d.positive_amount , d.id from its_debt d where id in (select d.id  from its_debt d where contract_id in (select id from its_contract where code = temprow.contract));




end if; 

exception when others then 
raise info '%',sqlerrm||' '|| temprow.contract||' '||log_id  ;

end;
end loop;	

update its_kafkalog set status=2 where id=log_id;

insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where id=log_id;

delete from its_kafkalog  where id=log_id;

end

$$;


--
-- Name: decrypt_b64(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrypt_b64(p_b64 text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pgcrypto', 'public'
    AS $$
  SELECT convert_from(
           decrypt(
             decode(p_b64,'base64'),
             convert_to('A9F2D8C7B6E1H4G3','UTF8'), 
             'aes-ecb'::text
           ),
           'UTF8'
         );
$$;


--
-- Name: encrypt_b64(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.encrypt_b64(p_text text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pgcrypto', 'public'
    AS $$
  SELECT encode(
           encrypt(
             convert_to(p_text, 'UTF8'),
             convert_to('A9F2D8C7B6E1H4G3','UTF8'), 
             'aes-ecb'::text
           ),
           'base64'
         );
$$;


--
-- Name: fnnumbertowords(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fnnumbertowords(n bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  e TEXT;
BEGIN

  WITH Below20(Word, Id) AS
  (
    VALUES
      ('ноль', 0), ('один', 1),( 'два', 2 ), ( 'три', 3),
      ( 'четыре', 4 ), ( 'пять', 5 ), ( 'шесть', 6 ), ( 'семь', 7 ),
      ( 'восемь', 8), ( 'девять', 9), ( 'десять', 10), ( 'одинадцать', 11 ),
      ( 'двенадцать', 12 ), ( 'тринадцать', 13 ), ( 'четырнадцать', 14),
      ( 'пятнадцать', 15 ), ('шестнадцять', 16 ), ( 'семьнадцать', 17),
      ('восемнадцать', 18 ), ( 'девятнадцать', 19 )
   ),
   Below100(Word, Id) AS
   (
      VALUES
       ('двадцать', 2), ('тридцать', 3),('сорок', 4), ('пятьдесят', 5),
       ('шестьдесят', 6), ('семьдесять', 7), ('восемьдесят', 8), ('девяноста', 9)
   ),
   Below1000(Word, Id) AS
   (
      VALUES
       ('сто', 1), ('двести', 2),('триста', 3), ('четыреста', 4)
      
   )
   SELECT
     CASE
  
      WHEN n = 0 THEN  ''
      WHEN n BETWEEN 1 AND 19
        THEN (SELECT Word FROM Below20 WHERE ID=n)
     WHEN n BETWEEN 20 AND 99
       THEN  (SELECT Word FROM Below100 WHERE ID=n/10) ||  ' '  ||
             fnNumberToWords( n % 10)
           WHEN n BETWEEN 100 AND 500
       THEN  (SELECT Word FROM Below1000 WHERE ID=n/100) || ' '  ||
             fnNumberToWords( n % 100)
 
     WHEN n BETWEEN 500 AND 999
       THEN  (fnNumberToWords( n / 100)) || ' сот ' ||
           fnNumberToWords( n % 100)
     WHEN n BETWEEN 1000 AND 999999
       THEN  (fnNumberToWords( n / 1000)) || ' тысяча ' ||
           fnNumberToWords( n % 1000)
     WHEN n BETWEEN 1000000 AND 999999999
       THEN  (fnNumberToWords( n / 1000000)) || ' миллионо ' ||
           fnNumberToWords( n % 1000000)
     WHEN n BETWEEN 1000000000 AND 999999999999
       THEN  (fnNumberToWords( n / 1000000000)) || ' миллиард ' ||
           fnNumberToWords( n % 1000000000)
     WHEN n BETWEEN 1000000000000 AND 999999999999999
       THEN  (fnNumberToWords( n / 1000000000000)) || ' триллион ' ||
           fnNumberToWords( n % 1000000000000)
    WHEN n BETWEEN 1000000000000000 AND 999999999999999999
       THEN  (fnNumberToWords( n / 1000000000000000)) || ' quadrillion ' ||
           fnNumberToWords( n % 1000000000000000)
    WHEN n BETWEEN 1000000000000000000 AND 999999999999999999999
       THEN  (fnNumberToWords( n / 1000000000000000000)) || ' quintillion ' ||
           fnNumberToWords( n % 1000000000000000000)
          ELSE ' INVALID INPUT' END INTO e;

  e := RTRIM(e);

  IF RIGHT(e,1)='-' THEN
    e := RTRIM(LEFT(e,length(e)-1));
  END IF;

  RETURN e;
END;
$$;


