--
-- Name: log_to_hst(bigint); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.log_to_hst(IN in_id bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN

insert into its_kafkalog_hst(packet_name,data,old_id,old_at)
select packet_name,data,id,created_at from its_kafkalog  where id = in_id;
delete from its_kafkalog  where id = in_id;

	END;
$$;


--
-- Name: read_fromhst(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.read_fromhst()
    LANGUAGE plpgsql
    AS $$
declare
temprow record;
	BEGIN
for temprow in select * from 	its_kafkalog_hst where  packet_name = 'Cat.BankovskieScheta' order by id loop

insert into its_kafkalog(data)
     select
     data
     from its_kafkalog_hst  s
      where packet_name = 'Cat.BankovskieScheta'   and s.id=temprow.id;
end loop;


	END;
$$;


--
-- Name: sync_bankaccount(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sync_bankaccount()
    LANGUAGE plpgsql
    AS $$
declare
v_packet varchar(100) := 'Cat.BankovskieScheta';
type varchar(100) := 'Cat.Kontragenty';
temprow record;
bankaccount_id bigint;
bank_id bigint;
its_cli_id bigint;
project_id bigint;
begin


--update its_kafkalog set status = 1 where status is null  and (data::json->'table'->>'Subject')  = v_packet  and (data::json->'value'->'Vladelets'->>'Type') = type;

for temprow in select * from its_kafkalog where (data::json->'table'->>'Subject') = v_packet and status = 1  and (data::json->'value'->'Vladelets'->>'Type') = type

order by id

loop



	bank_id := upsert_by_code('its_bank', jsonb_build_object
			(
				'code',temprow.data->'value'->'Bank'->>'ID',
				'title',temprow.data->'value'->'Bank'->>'View')
			);


    its_cli_id := upsert_by_code('its_cli', jsonb_build_object
			(
				'code',temprow.data->'value'->'Vladelets'->>'ID',
				'title',temprow.data->'value'->'Vladelets'->>'View')
			);
	project_id := upsert_by_code('projects', jsonb_build_object
	    ('code',temprow.data->'value'->'Proekt'->>'ID',
				'title',temprow.data->'value'->'Proekt'->>'View')
	    );
     	bankaccount_id := upsert_by_code('its_bankaccount', jsonb_build_object
            ('bank_id', bank_id,
             'its_cli_id', its_cli_id,
     	     'project_id',project_id,
             'code', temprow.data -> 'value' -> 'Ssylka' ->> 'ID',
             'title', temprow.data -> 'value' -> 'Ssylka' ->> 'View',
             'nomer_scheta', temprow.data -> 'value' ->> 'NomerScheta'
            ));

    call log_to_hst (temprow.id);

 


 end loop;




--exception when others then
--PERFORM  syncLog(v_procname,sqlerrm);
--raise info '%',sqlerrm||' '||v_procname;

end
$$;


