			);		

	project_id := upsert_by_code('projects', jsonb_build_object
	    ('code',temprow.data->'value'->'Proekt'->>'ID',
				'title',temprow.data->'value'->'Proekt'->>'View')
	    );
	bankaccount_id := upsert_by_code('its_bankaccount_company', jsonb_build_object
			(	'bank_id', bank_id, 
				'its_company_id', its_comp_id,
	            'project_id',project_id,
				'code',temprow.data->'value'->'Ssylka'->>'ID',
				'title',temprow.data->'value'->'Ssylka'->>'View',
	            'nomer_scheta',temprow.data->'value'->>'NomerScheta'
	         )
			);

    call log_to_hst (temprow.id);
   
    
  
  
 end loop;




--exception when others then
--PERFORM  syncLog(v_procname,sqlerrm);
--raise info '%',sqlerrm||' '||v_procname;

end;
$$;


--
-- Name: sync_buprojects_index(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sync_buprojects_index()
    LANGUAGE plpgsql
    AS $$
declare
type varchar(100) :='Cat.BU_Proekty';
packet varchar(100) := 'InfoRg.IndeksyNumeratsii';
temprow record;
begin
update its_kafkalog set status = 1 where status is null and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = type;

for temprow in select * from its_kafkalog where status =1 and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = type order by id loop
 update projects set idx = (temprow.data::json->'value'->>'Indeks') where code_1c=(temprow.data::json->'value'->>'KodBK');
   end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = type;
insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = type;
--delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = type ;
exception when others then
update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: sync_cliassignee(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sync_cliassignee()
    LANGUAGE plpgsql
    AS $$
declare
packet varchar(100) := 'InfoRg.BI_OtvetstvennyeLitsaKontragentov';
temprow record;
begin


update its_kafkalog set status = 1  where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop

insert into its_cli_assignee (code,title,authority_id,date,date2,email,iin,in_mailing_list,its_cli_assignee_id,number,signer,sklonenie_id,cli_biniin_id,cli_name)
    select distinct
concat((data::json)->'value'->'Podpisant'->>'ID',(data::json)->'value'->'Kontragent'->>'ID',(data::json)->'value'->>'Period')   as code ,
(data::json)->'value'->'Podpisant'->>'View'  as title,
(select id from its_foundation_authority where code=(data::json)->'value'->'OsnovaniePolnomochiy'->>'ID') as authority_id,
((data::json)->'value'->>'Period')::date  as date,
((data::json)->'value'->>'DataDokumentaOsnovaniya')::date  as date2,
(data::json)->'value'->>'Email'  as email,
(data::json)->'value'->>'IIN'  as iin,
(case when (data::json)->'value'->>'PoluchaetRassylku'= 'true' then 1 else 0 end)  as in_mailing_list,
(select id from its_responsible_cliper where code=(data::json)->'value'->'OtvetstvennoeLitso'->>'ID') as its_cli_assignee_id,
(data::json)->'value'->>'NomerDokumentaOsnovaniya'  as number,
(select id from its_cli_signatories where code=(data::json)->'value'->'Podpisant'->>'ID') as signer,
(data::json)->'value'->>'PodpisantVRodPadezhe'  as sklonenie_id,
(data::json)->'value'->>'KontragentIIN' as cli_biniin_id,
(data::json)->'value'->'Kontragent'->>'View' as cli_name
from its_kafkalog
    where (data::json->'table'->>'Subject') = packet  and status=1 and id=temprow.id
    on conflict (code) do update set title =excluded.title,authority_id= excluded.authority_id,date = excluded.date,date2=excluded.date2,email=excluded.email,
                                     iin=excluded.iin,in_mailing_list=excluded.in_mailing_list,its_cli_assignee_id=excluded.its_cli_assignee_id,number=excluded.number,
                                     signer=excluded.signer,sklonenie_id=excluded.sklonenie_id,cli_biniin_id=excluded.cli_biniin_id,cli_name=excluded.cli_name;


end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2 and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;
  



end;
$$;


