--
-- Name: sync_plan_accrual(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sync_plan_accrual()
    LANGUAGE plpgsql
    AS $$
declare
    procname varchar(100) :='sync_plan_accrual';
    packet varchar(100) := 'InfoRg.PlanovyeNachisleniya';
    temprow  record;
    plan_reg_accrual_id bigint;
    head_organization_id bigint;
begin
for temprow in select * from its_kafkalog  where  (data::json->'table'->>'Subject') = packet

order by id

    loop
    head_organization_id := upsert_by_code
        (
        'companies',
        jsonb_build_object
            (
                'code',temprow.data->'value'->'GolovnayaOrganizatsiya'->>'ID',
				'title',temprow.data->'value'->'GolovnayaOrganizatsiya'->>'View'
            )
        );

    plan_reg_accrual_id := upsert_by_code
        (
        'its_plan_accrual_reg',
        jsonb_build_object
            (
                'code', concat(
                                (temprow.data::json) -> 'key' ->> 'Nachislenie',
                                (temprow.data::json) -> 'key' ->> 'Period',
                                (temprow.data::json) -> 'key' ->> 'Sotrudnik',
                                (temprow.data::json) -> 'key' ->> 'Registrator',
                                (temprow.data::json) -> 'key' ->> 'FizicheskoeLitso',
                                (temprow.data::json) -> 'key' ->> 'DokumentOsnovanie',
                                (temprow.data::json) -> 'key' ->> 'GolovnayaOrganizatsiya',
                                random() * 10 + 1
                    ),
                'accrual_text', (temprow.data::json) -> 'value' -> 'Nachislenie' ->> 'View',
                'doc_osnov', (temprow.data::json) -> 'value' ->> 'DokumentOsnovanie',
                'fiz_litso_text', (temprow.data::json) -> 'value' -> 'FizicheskoeLitso' ->> 'View',
                'head_organization_id', head_organization_id,
                'registrator_text', (temprow.data::json)->'value'->'Registrator'->>'View',
                'sotrudnik',(temprow.data::json)->'value'->'Sotrudnik'->>'View',
                'title',concat
                        (
                            (temprow.data::json)->'value'->'Nachislenie'->>'View',' ',
                            (temprow.data::json)->'value'->'Sotrudnik'->>'View', ' ',
                            (temprow.data::json)->'value'->'Period'
                        ),
                'active',(case when (temprow.data::json)->'value'->>'Aktivnost' = 'true' then 1 else 0 end),
                'in_use',(case when (temprow.data::json)->'value'->>'Ispolzuetsya' = 'true' then 1 else 0 end),
                'is_secondary',(case when (temprow.data::json)->'value'->>'IVtorichnayaZapis' = 'true' then 1 else 0 end),
                'is_used_after',(case when (temprow.data::json)->'value'->>'IspolzuetsyaPoOkonchanii' = 'true' then 1 else 0 end) ,
                'line_numbet_text', ((temprow.data::json)->'value'->>'NomerStroki' ) ,
                'period',(to_timestamp((temprow.data::json)->'value'->>'Period', 'YYYY-MM-DDThh24:mi:ssZ')::timestamp) ,
                'recalc_no_need',(case when (temprow.data::json)->'value'->>'PereschetNeTrebuetsya' = 'true' then 1 else 0 end) ,
                'size_text',((temprow.data::json)->'value'->>'Razmer') ,
                'size_end_text',((temprow.data::json)->'value'->>'RazmerPoOkonchanii'),
                'valid_end_date',(to_timestamp((temprow.data::json)->'value'->>'DeystvuetDo','YYYY-MM-DDThh24:mi:ssZ')::timestamp)

            )
        );
       -- call log_to_hst (temprow.id);


    end loop;
     end;

$$;


