order by id 

loop

	
	roditel_id := upsert_by_code('its_ref_podvidytovarovuslug', jsonb_build_object
			(
				'code',temprow.data->'value'->'Roditel'->>'ID',
				'title',temprow.data->'value'->'Roditel'->>'View')
			);
	vladelets_id := upsert_by_code('its_ref_item_type', jsonb_build_object
			(
				'code',temprow.data->'value'->'Vladelets'->>'ID',
				'title',temprow.data->'value'->'Vladelets'->>'View')
			);
	vid_dogovora_id := upsert_by_code('its_contract_item', jsonb_build_object
			(
				'code',temprow.data->'value'->'VidDogovora'->>'ID',
				'title',temprow.data->'value'->'VidDogovora'->>'View')
			);
	edinitsa_izmereniya_id := upsert_by_code('its_unit', jsonb_build_object
			(
