				'title',temprow.data->'value'->'EdinitsaIzmereniya'->>'View')
			);

	podvidy_id := upsert_by_code('its_ref_podvidytovarovuslug', jsonb_build_object
			(	
				'roditel_id', roditel_id,
	             'vladelets_id',vladelets_id,
	             'vid_dogovora_id',vid_dogovora_id,
