	            'kod_1c',temprow.data->'value'->>'Kod',
	            'tsena',temprow.data->'value'->>'Tsena',
	            'eto_gruppa',case when temprow.data->'value'->>'EtoGruppa'= 'true' then 1 else 0 end ,
                'is_delete',case when temprow.data->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end ,
	            'predopredelennyy',case when temprow.data->'value'->>'Predopredelennyy'= 'true' then 1 else 0 end ,
	            'imya_predopredelennykh',temprow.data->'value'->>'ImyaPredopredelennykhDannykh'
	        )
			);
		

    call log_to_hst (temprow.id);
   
   
  
  
 end loop;


end;
$$;


