dogovor_id bigint;
begin
update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = v_packet;
for temprow in select * from its_kafkalog where  (data::json->'table'->>'Subject') = v_packet and status = 1
order by id

loop

	parent_id := upsert_by_code('its_ref_item_type', jsonb_build_object
			(
				'code',temprow.data->'value'->'Roditel'->>'ID',
				'title',temprow.data->'value'->'Roditel'->>'View')
			);
     dogovor_id := upsert_by_code('its_contract_item', jsonb_build_object
			(
				'code',temprow.data->'value'->'BI_VidDogovora'->>'ID',
				'title',temprow.data->'value'->'BI_VidDogovora'->>'View')
			);
    its_unit_id := upsert_by_code('its_unit', jsonb_build_object
			(
				'code',temprow.data->'value'->'EdinitsaIzmereniya'->>'ID',
				'title',temprow.data->'value'->'EdinitsaIzmereniya'->>'View')
			);

	 regtovaruslugy_id := upsert_by_code('its_ref_item_type', jsonb_build_object
			  (
           'ed_id',its_unit_id,
           'tovar_uslugy_id',parent_id,
	       'dogovor_id',dogovor_id,
           'code',temprow.data->'value'->'Ssylka'->>'ID',
           --'title',temprow.data->'value'->'Ssylka'->>'View' ,
           'is_delete',case when temprow.data->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end,
	       'is_file',case when temprow.data->'value'->>'EtoGruppa'= 'true' then 1 else 0 end,
           'kod_onec',temprow.data->'value'->>'Kod',
	       'kod_bk',temprow.data->'value'->>'KodBK'
     ));
    
   -- call log_to_hst (temprow.id);

  
  
 end loop;




end;
$$;


--
-- Name: syncaccrualtype(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncaccrualtype()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncAccrualType';
packet varchar(100) := 'Cat.VidyZadolzhenostiKSK';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop


insert into its_accrual_type(code,title,kod,is_delete)
select distinct 
(data)->'value'->'Ssylka'->>'ID'  as code ,
(data)->'value'->'Ssylka'->>'View' as title,
(data)->'value'->>'Kod' as kod,
(case when (data)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end ) as is_delete

from its_kafkalog 
    where (data->'table'->>'Subject') = packet and status=1 and id=temprow.id
   on conflict(code) do update set is_delete=excluded.is_delete;

  end loop;
 
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


