--
-- Name: synccli(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synccli()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncCli';
packet varchar(100) := 'Cat.Partners';
temprow record;
begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop


insert into its_cli (code,title,type_id ,kind_id,bin_iin,kod,company_id,vip,problemnyy_kontragent)
    select distinct 
(data::json)->'value'->'Ssylka'->>'ID'  as code ,
(data::json)->'value'->'Ssylka'->>'View'  as title ,
(select id from its_cliref_type  where code=(data::json)->'value'->'YurFizLitso'->>'ID')  as type_id,
(select id from its_cliref_kind  where code=(data::json)->'value'->'Roditel'->>'ID')  as kind_id,
(data::json)->'value'->>'IdentifikatsionnyyKodLichnosti'  as bin_iin ,
(data::json)->'value'->>'Kod'  as kod,
 --(case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
(select id from companies c where  c.bin=(data::json)->'value'->>'IdentifikatsionnyyKodLichnosti'  and   is_delete not in(1) and dont_use not in(1) 
and bin  not in('160640024476') and  (c.bin='') IS NOT true  ) as company_id ,
(case when (data::json)->'value'->>'VIP'='true' then 1 else 0 end ) as vip,
(case when (data::json)->'value'->>'ProblemnyyKontragent'='true' then 1 else 0 end ) as problemnyy_kontragent
from its_kafkalog
    where (data::json->'table'->>'Subject') = packet  and status=1 and id=temprow.id
    on conflict (code) do update set title =excluded.title,bin_iin =excluded.bin_iin,kind_id =excluded.kind_id,
   type_id =excluded.type_id,kod =excluded.kod,company_id=excluded.company_id,vip=excluded.vip,problemnyy_kontragent=excluded.problemnyy_kontragent;
end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: synccli_contact(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synccli_contact()
    LANGUAGE plpgsql
    AS $$
declare
packet varchar(100) := 'Cat.KontragentyDoc';
temprow record;
step varchar;
begin


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in 	select  id,
    data::json->'value'->>'INN' as bin,
    data->'value'->'KontaktnayaInformatsiya'   as cont
    from its_kafkalog
	where  (data::json->'table'->>'Subject') = packet and  data->'value'->'KontaktnayaInformatsiya' !='[]'  order by id loop
	begin

   step='2';
     insert into its_cli_contact (title, type_id,cli_id)
      select * from (select s.title,
     	(select id from its_cli_cont_types where code=s.type_id LIMIT 1) as type_id,s.cli_id
     from
     (select
     jsonb_array_elements(temprow.cont)->>'Predstavlenie' as title,
     jsonb_array_elements(temprow.cont)->'Vid'->>'ID' as type_id,
     (select id from its_cli where bin_iin=temprow.bin LIMIT 1) as cli_id) s ) d
     where not exists (select 1 from its_cli_contact c where c.title=d.title and c.cli_id=d.cli_id)
     and d.cli_id is  not null;

    end;

	end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

end;
$$;


--
-- Name: syncclicontact(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncclicontact()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncCliContact';
packet varchar(100) := 'InfoRg.KontaktnayaInformatsiya';
object varchar(100) := 'Cat.Kontragenty';

begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Object'->>'Type') = object;


insert into its_cli_contact(cli_id,title,digits,type_id)
select  ic.id,(data::json)->'value'->>'Predstavlenie',regexp_replace((data::json)->'value'->>'Predstavlenie', '[^[:digit:]]','','g') , (select id from  its_cli_cont_types where code = (data::json)->'value'->'Vid'->>'ID')
from its_kafkalog s,its_cli ic where  (data::json->'table'->>'Subject')=  packet and (data::json->'value'->'Object'->>'Type') = object and
(data::json)->'value'->'Object'->>'ID' =ic.code and status=1
and not exists(select 1 from its_cli_contact t where t.cli_id=ic.id and t.title=(data::json)->'value'->>'Predstavlenie');

  
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Object'->>'Type') = object;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Object'->>'Type') = object;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Object'->>'Type') = object;


-- exception when others then
-- call syncLog(procname,sqlerrm);
-- raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: synccompanies(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synccompanies()
    LANGUAGE plpgsql
    AS $$
declare
procname varchar(100) :='syncCompanies';
packet varchar(100) := 'Cat.Organizatsii';
temprow record;

begin


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;
for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop
INSERT INTO companies (code,title,bin,inagro_division_id,holding_id,prefix,is_delete,dont_use)
select distinct
    (data::json->'value'->'Ssylka'->>'ID') as code,
    (data::json->'value'->'Ssylka'->>'View') as title,
    (data::json->'value'->>'IdentifikatsionnyyNomer') as bin,
    (select id from inagro_division d where d.code=(data::json->'value'->'Divizion'->>'ID'  ) limit 1) as inagro_division_id,
    (select id from holding d where d.title=(data::json->'value'->'NomerKholdinga'->>'View' ) limit 1) as holding_id,
    (data::json->'value'->>'Prefiks') as prefix ,
    (case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
                 (case when (data::json)->'value'->>'NeIspolzovatElementSpravochnika'= 'true' then 1 else 0 end)  as dont_use

from its_kafkalog
    where (data::json->'table'->>'Subject') = packet and status=1 and id=temprow.id
       on CONFLICT(code) do update set title=EXCLUDED.title,bin=EXCLUDED.bin,inagro_division_id=EXCLUDED.inagro_division_id,holding_id=EXCLUDED.holding_id,prefix=EXCLUDED.prefix,is_delete=EXCLUDED.is_delete,dont_use =EXCLUDED.dont_use;


  end loop;


update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

end;
$$;


--
-- Name: synccompanies_dop(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synccompanies_dop()
    LANGUAGE plpgsql
    AS $$
declare 
packet varchar(100) := 'Cat.OrganizatsiiDoc';
temprow record;
step varchar;
begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in 	select  id,
    data::json->'value'->>'INN' as bin,
    data->'value'->'DopolnitelnyeRekvizity' as cont,
    data->'value'->'KontaktnayaInformatsiya' as con
    from its_kafkalog
	where  (data::json->'table'->>'Subject') = packet  order by id loop
	begin
	step='1';
   	insert into its_dop_rekvizity(code,title)
	select s.* from (select jsonb_array_elements(temprow.cont)->'Svoystvo'->>'ID' as code,jsonb_array_elements(temprow.cont)->'Svoystvo'->>'View' as title )
	s
    on conflict(code) do update set title=EXCLUDED.title;
   step='2';
     insert into its_dop_rekvizity_company (value_txt, dop_rekvezity_id, companies_id)
      select * from (select s.value_txt,
     	(select id from its_dop_rekvizity where code=s.dop_rekvezity_id ) as type_id,s.companies_id
     from
     (select
     jsonb_array_elements(temprow.cont)->>'Znachenie' as value_txt,
     jsonb_array_elements(temprow.cont)->'Svoystvo'->>'ID' as dop_rekvezity_id,
     (select id from companies where bin=temprow.bin limit 1) as companies_id) s ) d
     where not exists (select 1 from its_dop_rekvizity_company c where c.value_txt=d.value_txt and c.companies_id=d.companies_id)
     and d.companies_id is  not null and d.type_id in (select id from its_dop_rekvizity);
   step='3';
     insert into its_company_contacts (value_txt, cont_types, companies_id)
      select * from (select s.value_txt,
     	(select id from cont_types where do_analog_code=s.dop_id ) as type_id,s.companies_id
     from
     (select
     jsonb_array_elements(temprow.con)->>'Predstavlenie' as value_txt,
     jsonb_array_elements(temprow.con)->'Vid'->>'ID' as dop_id,
     (select id from companies where bin=temprow.bin limit 1) as companies_id) s ) d
     where not exists (select 1 from its_company_contacts c where c.value_txt=d.value_txt and c.companies_id=d.companies_id)
     and d.companies_id is  not null and d.type_id in (select id from cont_types);


    --exception when others then
  	--call syncLog(procname,temprow.id::text||' '||sqlerrm);
   -- update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
	--raise info '%',sqlerrm||' '||procname||' '||step||' log_id='||temprow.id;
    end;


	end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

end;
$$;


