(data::json)->'value'->'Obekt'->>'ID' =ic.code and status=1
and not exists(select 1 from its_company_contacts t where t.companies_id=ic.id and t.value_txt=(data::json)->'value'->>'Predstavlenie');

  
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet and (data::json->'value'->'Obekt'->>'Type') = object;


