CREATE PROCEDURE public.synccontract()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncContract';
packet varchar(100) := 'Cat.DogovoryKontragentov';
temprow record;
begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop


insert into its_contract(code,title,is_delete,user_id,bi_user_id,kod,contract_date,subject,company_id,project_id,cli_id,currency_id,start_date,end_date,bessroka,summa)
select distinct 
(data::json)->'value'->'Ssylka'->>'ID'  as code ,
(data::json)->'value'->'Ssylka'->>'View' as title,
(case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
(select id from users where code=(data::json)->'value'->'Otvestvenyy'->>'ID') as user_id,
(select id from users where code=(data::json)->'value'->'Avtor'->>'ID') as bi_user_id,
(data::json)->'value'->>'Kod' as kod,
((data::json)->'value'->>'DataDogovora')::date as contract_date,
(data::json)->'value'->>'PredmetDogovora' as subject,
(select id from companies where code=(data::json)->'value'->'Organizatsiya'->>'ID') as company_id,
(select id from projects where code=(data::json)->'value'->'Proekt'->>'ID') as project_id,
(select id from its_cli where code=(data::json)->'value'->'Vladelets'->>'ID') as cli_id,
(select id from its_currency where code=(data::json)->'value'->'ValyutaVzaimoraschetov'->>'ID') as currency_id,
((data::json)->'value'->>'DataNachalaDeystviyaDogovora')::date as start_date,
((data::json)->'value'->>'DataOkonchaniyaDeystviyaDogovora')::date as end_date,
(case when (data::json)->'value'->>'Bessrochnyy'= 'true' then 1 else 0 end)  as bessroka,
((data::json)->'value'->>'SummaDogovora') as summa
from its_kafkalog
    where (data::json->'table'->>'Subject') = packet and status=1 and id=temprow.id
   on conflict(code) do update set title=excluded.title,is_delete=excluded.is_delete,user_id=excluded.user_id,bi_user_id=excluded.bi_user_id,kod=excluded.kod,
  contract_date=excluded.contract_date,subject=excluded.subject,company_id=excluded.company_id,project_id=excluded.project_id,cli_id=excluded.cli_id,currency_id=excluded.currency_id,
                                   start_date = excluded.start_date,end_date=excluded.end_date,bessroka = excluded.bessroka,summa= excluded.summa;

  end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


-- exception when others then
-- call syncLog(procname,sqlerrm);
-- raise info '%',sqlerrm||' '||procname;

end;
$$;


