--
-- Name: syncdebt(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncdebt()
    LANGUAGE plpgsql
    AS $$
DECLARE
temprow  RECORD;
temprow2  RECORD;
debt_id bigint;
begin 
update its_debt_log set status=1 where status is null;
commit;

for temprow2 in select s.* from its_debt_log s where s.status =1 loop 
	
for temprow in  select (elements->>'Debt') as debt, (elements->>'Client') as client,(elements->>'Contract') as contract ,to_date((elements->>'DZFormationDate'),'yyyy-mm-dd') as DZFormationDate,(elements->>'City') as city,(elements->>'CityName') as cityname,(elements->>'Zone') as zonename,
(elements->>'PropertyType') as its_premises_type,(elements->>'PropertyTypeName') as its_premises_type_name,(elements->>'Property') as its_premises,(elements->>'PropertyNumber') as its_premises_name,(elements->>'Object') as objectid,(elements->>'ObjectName') as object_name,(elements->>'AccauntNumber') as account_number
from its_debt_log
CROSS JOIN lateral jsonb_array_elements(data) elements 
where id = temprow2.id loop 	


insert into its_debt(amount,cli_id,contract_id,formation_date,city_id,its_uchastkion_id,its_premises_type_id,its_premises_id,its_real_estate_id,account_number)
select temprow.debt::double precision
 as amount, (select id from its_cli where code=temprow.client) as cli_id ,
  id  as contract_id ,
 temprow.DZFormationDate as formation_date,
 upsert(temprow.cityname,temprow.city,'its_city') as city_id,
 (select id from its_uchastkion where title =temprow.zonename) as its_uchastkion_id,
 upsert(temprow.its_premises_type_name,temprow.its_premises_type,'its_premises_type') as its_premises_type_id,
 upsert(temprow.its_premises_name,temprow.its_premises,'its_premises') as its_premises_id,
 upsert(temprow.object_name,temprow.objectid,'its_real_estate') as its_real_estate_id,
 temprow.account_number as account_number
 
 
 from its_contract where code = temprow.contract
 on conflict (contract_id,formation_date) do update set amount=excluded.amount,city_id=excluded.city_id,its_uchastkion_id=excluded.its_uchastkion_id,its_premises_type_id=excluded.its_premises_type_id,
its_premises_id=excluded.its_premises_id,its_real_estate_id=excluded.its_real_estate_id,account_number=excluded.account_number ;

commit;
begin  
select d.id into debt_id from its_debt d where contract_id =(select id from its_contract where code = temprow.contract)
and formation_date =temprow.DZFormationDate;

 
insert into its_debt_accruals(its_debt_id,amount,type_id,formation_date)
  select distinct debt_id as its_debt_id,s.accrual ::double precision as amount, (select id from its_accrual_type where code=s.actype) as type_id, to_date(s.acdate ,'yyyy-mm-dd') as formation_date from (
     select  elements,(elements->>'Debt') as debt,(elements->>'Client') as client,(elements->>'Contract') as contract ,to_date((elements->>'DZFormationDate'),'yyyy-mm-dd') as DZFormationDate, 
     jsonb_array_elements((elements->>'Accruals')::jsonb)->>'Debt' as  accrual,
     jsonb_array_elements((elements->>'Accruals')::jsonb)->>'AccrualType' as actype ,
   jsonb_array_elements((elements->>'Accruals')::jsonb)->>'DZFormationDate' as acdate 
from its_debt_log l
CROSS JOIN lateral jsonb_array_elements(data) elements
where l.id = temprow2.id  and (elements->>'Contract') =temprow.contract) s where s.actype not in ( '00000000-0000-0000-0000-000000000000')

and s.contract=temprow.contract
on conflict (its_debt_id,type_id) do update  set amount=excluded.amount;

exception when others then

raise info '%',sqlerrm||'  debt_id '||debt_id ||'  temprow '||temprow2.id ||'  contract '||temprow.contract; 
end;

commit;

update its_debt d
set positive_amount =(select coalesce((select sum(amount) from its_debt_accruals where amount>0 and its_debt_id=d.id),0))
where d.id=debt_id;
commit;

insert into its_debt_hst(amount,positive_amount,debt_id)
select d.amount ,d.positive_amount , d.id from its_debt d where id= debt_id;
commit;

end loop;	

update its_debt_log set status=2 where id=temprow2.id;
commit;

end loop;
end

$$;


--
-- Name: syncdep(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncdep()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncDep';
packet varchar(100) := 'Cat.PodrazdeleniyaOrganizatsiy';
temprow record;
begin 
update its_kafkalog set status = 1 where status is null and  (data::json->'table'->>'Subject') = packet;	

for temprow in select * from its_kafkalog where status=1 and (data::json->'table'->>'Subject') = packet order by id  loop 
 INSERT INTO deps (code,title,ext_code,is_archive,title_perevod,nn_field,raion_koef,is_detached,formed,created_at,deformed,deformed_dt,company_id,okved,del_add_holiday_y)

    select distinct
    (data::json->'key'->>'Ssylka') as code,
    (data->'value'->>'Naimenovanie') as title,
    (data::json->'value'->>'Kod') as ext_code,
    case when (data::json->'value'->>'BI_NeIspolzovatSpravochnik')='true' then 1 else 0 end as is_archive,
    (data::json->'value'->>'BI_NaimenovaniePerevod') as title_perevod,
    (data::json->'value'->>'RekvizitDopUporyadochivaniya')::numeric as nn_field,
    (data::json->'value'->>'RayonnyyKoeffitsient')::numeric as raion_koef,
    case when (data::json->'value'->>'ObosoblennoePodrazdelenie')='true' then 1 else 0 end as is_detached,
    case when(data::json->'value'->>'Sformirovano')='true' then 1 else 0 end as formed,
    TO_DATE((data::json->'value'->>'DataSozdaniya'),'YYYY-MM-ddTHH24:MI:SSZ') as created_at,
    case when (data::json->'value'->>'Rasformirovano')='true' then 1 else 0 end as deformed,
    TO_DATE((data::json->'value'->>'DataRasformirovaniya'),'YYYY-MM-ddTHH24:MI:SSZ') as deformed_dt,
    (select id from companies where code=(data::json->'value'->'GolovnayaOrganizatsiya'->>'ID')) as company_id,
    (data::json->'value'->>'KodOKVED') as okved,
    (data::json->'value'->>'UdalitKolichestvoDopolnitelnykhDneyOtpuskaVGod')::numeric as del_add_holiday_y
     from its_kafkalog
    where (data::json->'table'->>'Subject') = packet
    and status = 1 and id =temprow.id
    
    ON CONFLICT (code) DO UPDATE SET title = EXCLUDED.title,ext_code = EXCLUDED.ext_code,is_archive = EXCLUDED.is_archive,title_perevod = EXCLUDED.title_perevod,
    
    nn_field =  EXCLUDED.nn_field,
    raion_koef = EXCLUDED.raion_koef,
    is_detached=  EXCLUDED.is_detached,
    formed=  EXCLUDED.formed,
