temprow record;
cnt int;
begin

update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in 	select * from its_kafkalog ik  where  (data::json->'table'->>'Subject') = packet and status =1 order by id loop

insert into users_companies_discip(code,dscr,doc_date,doc_num,reason,users_companies_id,type_id)
select
t.parent->'value'->'Ssylka'->>'ID' as code,
t.parent->'value'->'Ssylka'->>'View' as dscr,
to_date(t.parent->'value'->>'BI_DataPrikaza','yyyy-mm-dd') as doc_date,
