Upsert(t.data->'VidNakazaniya'->>'View',t.data->'VidNakazaniya'->>'ID','its_discip_type') as type_id
from
 (
select jsonb_array_elements(data->'value'->'Sotrudniki') as data,data as parent from its_kafkalog s
where s.id =temprow.id  and  s.data->'value'->>'Proveden'= 'true' limit 1) t
on conflict (code) do update set dscr=excluded.dscr,doc_date=excluded.doc_date,doc_num=excluded.doc_num,reason=excluded.reason,users_companies_id=excluded.users_companies_id,type_id=excluded.type_id;


