--
-- Name: syncgph(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncgph()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncGPh';
packet varchar(100) := 'Cat.BI_SotrudnikiGPKh';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop

insert into emp_gph(code,title,users_id,deps_id,project_id,company_id,is_delete,is_arch)
     select 
     (data::json)->'value'->'Ssylka'->>'ID'  as code ,
    
     (data::json)->'value'->>'Naimenovanie'  as title ,
      u.id as user_id,
      (select id from deps where code=(data::json)->'value'->'PodrazdelenieOrganizatsii'->>'ID') as deps_id,
      (select id from projects where code=(data::json)->'value'->'Proekt'->>'ID') as project_id,
      (select id from companies where code=(data::json)->'value'->'GolovnayaOrganizatsiya'->>'ID') as company_id,
          (case when (s.data::json)->'value'->>'PometkaUdaleniya' = 'true' then 1 else 0 end) as is_delete,
    (case when (s.data::json)->'value'->>'VArkhive' = 'true' then 1 else 0 end) as is_arch
     from its_kafkalog  s
     join users u on u.code=  (data::json)->'value'->'FizicheskoeLitso'->>'ID' 
      where (data::json->'table'->>'Subject') = packet  and status=1 and s.id=temprow.id
      on conflict(code) do update set title=EXCLUDED.title,deps_id=EXCLUDED.deps_id,project_id=EXCLUDED.project_id,company_id=EXCLUDED.company_id,is_delete=EXCLUDED.is_delete,is_arch=EXCLUDED.is_arch;
end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: syncgphhst(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncgphhst()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncGPhHst';
packet varchar(100) := 'InfoRg.KadrovayaIstoriyaSotrudnikovGPKh';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;
--status = 1  and
for temprow in select * from 	its_kafkalog where status = 1  and (data::json->'table'->>'Subject') = packet order by id loop

begin
insert into emp_gph(code,title,users_id,deps_id,project_id,company_id,is_delete,is_arch)
     select 
     (data::json)->'value'->'Sotrudnik'->>'ID'  as code ,
     (data::json)->'value'->'Sotrudnik'->>'View'  as title ,
      u.id as user_id,
      Upsert((data::json)->'value'->'Podrazdelenie'->>'ID',(data::json)->'value'->'Podrazdelenie'->>'ID','deps') as deps_id,
      Upsert((data::json)->'value'->'Proekt'->>'View',(data::json)->'value'->'Proekt'->>'ID','projects') as project_id,
      (select id from companies where code =(data::json)->'value'->'GolovnayaOrganizatsiya'->>'ID' )  as company_id,
         (case when (s.data::json)->'value'->>'PometkaUdaleniya' = 'true' then 1 else 0 end) as is_delete,
    (case when (s.data::json)->'value'->>'VArkhive' = 'true' then 1 else 0 end) as is_arch
     from its_kafkalog  s
     join users u on u.code=  (data::json)->'value'->'FizicheskoeLitso'->>'ID' 
     where (data::json->'table'->>'Subject') = packet  and status=1 and s.id=temprow.id
     on conflict(code) do update set title=EXCLUDED.title,deps_id=EXCLUDED.deps_id,project_id=EXCLUDED.project_id,company_id=EXCLUDED.company_id,is_delete=EXCLUDED.is_delete,is_arch=EXCLUDED.is_arch;
  
    insert into users_companies(code,users_id,company_id,work_type_id)
    select   distinct 
    (data::json)->'value'->'FizicheskoeLitso'->>'ID' as code ,
    r.id as users_id ,
    (select id from companies where code =(data::json)->'value'->'GolovnayaOrganizatsiya'->>'ID' ) as company_id,
    (select w.id from work_type w where code='ОсновноеМестоРаботы') as work_type_id
    from its_kafkalog  e
    join users r on r.code=(data::json)->'value'->'FizicheskoeLitso'->>'ID'
    where (data::json->'table'->>'Subject') = packet and status=1  and e.id=temprow.id
    on conflict (code) do update set company_id=EXCLUDED.company_id,work_type_id=EXCLUDED.work_type_id ;

exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;
end;
     
end loop;



update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;



end;
$$;


