--
-- Name: synchrhyst(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synchrhyst()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncHrHyst';
packet varchar(100) := 'InfoRg.KadrovayaIstoriyaSotrudnikov';
temprow record;
step varchar;
begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;
	step=' 1';
for temprow in select  (data::json)->'key'->>'Sotrudnik' as code ,max(to_date((data::json)->'key'->>'Period','yyyy-mm-dd')) as max_date
from its_kafkalog s
where s.data->'table'->>'Subject'=packet and status =1
group by (data::json)->'key'->>'Sotrudnik' loop 	

step=' 2';
update users_companies u
set company_id =(select id from companies where code=data->'key'->>'GolovnayaOrganizatsiya'),
hr_position_id = (select id from hr_position p where p.code= (data::json)->'value'->'Dolzhnost'->>'ID'),
project_id=(select id from projects p where p.code=(data::json)->'value'->'INAGRO_ProektOrganizatsii'->>'ID'),
emp_type = (data::json)->'value'->'VidZanyatosti'->>'View'
from its_kafkalog s
where s.data->'table'->>'Subject'=packet and status=1
and (data::json)->'key'->>'Sotrudnik'=u.code 
and (data::json)->'key'->>'Sotrudnik'=temprow.code
and to_date((data::json)->'key'->>'Period','yyyy-mm-dd')=temprow.max_date;


end loop;


update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname||step;

end;
$$;


--
-- Name: synchrposition(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synchrposition()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncHRPosition';
packet varchar(100) := 'Cat.Dolzhnosti';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop	
	
 INSERT INTO hr_position (code,title,dont_use,is_arch)
select (data::json)->'value'->'Ssylka'->>'ID'  as code, (data::json)->'value'->'Ssylka'->>'View'  as title,
(case when (data::json)->'value'->> 'BI_NeIspolzovatSpravochnik'='true' then 1 else 0 end ) as dont_use ,
(case when (data::json)->'value'->> 'PometkaUdaleniya' ='true' then 1 else 0 end ) as is_arch
from its_kafkalog s
where (data::json->'table'->>'Subject')=packet and status =1 and s.id=temprow.id
group by 
(data::json)->'value'->'Ssylka'->>'ID', 
(data::json)->'value'->'Ssylka'->>'View',
(data::json)->'value'->> 'BI_NeIspolzovatSpravochnik',
(data::json)->'value'->> 'PometkaUdaleniya' 
 ON CONFLICT (code) DO UPDATE set dont_use =  EXCLUDED.dont_use,
    is_arch = EXCLUDED.is_arch, title = excluded.title;

   
   update hr_position p 
set parent_id=(select hp.id from hr_position hp  where hp.code = (data::json)->'value'->'Roditel'->>'ID')
from its_kafkalog s
where (data::json->'table'->>'Subject')=    packet  and p.code= (data::json)->'value'->'Ssylka'->>'ID' and status =1 and s.id=temprow.id;


insert into hr_position_level(code,title)
select distinct  (data::json)->'value'->'INAGRO_UrovenDolzhnosti'->>'ID'  as code, (data::json)->'value'->'INAGRO_UrovenDolzhnosti'->>'View'  as title
from its_kafkalog s
where (data::json->'table'->>'Subject')=packet and (data::json)->'value'->'INAGRO_UrovenDolzhnosti'->>'ID' is not null and status =1 and s.id=temprow.id
on CONFLICT(code) do nothing;

update hr_position h
set greydy_id= (select i.id from its_greydy i where code=(data::json)->'value'->'INAGRO_Greyd'->>'ID' ),
level_id=(select h.id from hr_position_level h where code =(data::json)->'value'->'INAGRO_UrovenDolzhnosti'->>'ID' ),
type =(data::json)->'value'->'INAGRO_VidPersonala'->>'View'
from its_kafkalog s
where (data::json->'table'->>'Subject')=packet and status =1 and s.id=temprow.id
and h.code=(data::json)->'value'->'Ssylka'->>'ID';
 
end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


/*exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||''||procname;*/

end;
$$;


