temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop
	
 insert into inagro_division(code,title,is_delete,kod)
     select distinct 
     (data::json)->'value'->'Ssylka'->>'ID'  as code ,
      (data::json)->'value'->'Ssylka'->>'View'  as Naimenovanie,
   	  (case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
   	   (data::json)->'value'->>'Kod' as kod
      from its_kafkalog  s
      where (data::json->'table'->>'Subject') = packet  and status=1 and s.id=temprow.id
      on conflict (code) do update set is_delete=excluded.is_delete;
 
     end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: syncinagrotop(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncinagrotop()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncInagroTop';
packet varchar(100) := 'Cat.INAGRO_TOP';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop	
	
  insert into inagro_top(code,title,is_delete)
     select distinct 
     (data::json)->'value'->'Ssylka'->>'ID'  as code ,
      (data::json)->'value'->>'Naimenovanie'  as Naimenovanie ,
   (case when (data::json)->'value'->>'PometkaUdaleniya'='true' then 1 else 0 end )  as is_delete
     from its_kafkalog  s
      where (data::json->'table'->>'Subject') = packet and status=1 and s.id=temprow.id
      on conflict (code) do update set is_delete=excluded.is_delete;
     
  insert into inagro_top_greydy(graydy_id,inagro_top_id)
     select      (select id from its_greydy y where y.code= greid_code) as greid_id, top_id from (
     select   json_array_elements(s.data::json)->'Greyd'->>'ID' as greid_code,s.top_id from ( 
     select  distinct 
     (data::json)->'value'->>'Greydy'  as data , (select id from inagro_top where code= (data::json)->'value'->'Ssylka'->>'ID'  ) as top_id
     from its_kafkalog  s
      where (data::json->'table'->>'Subject') = packet and status=1 and s.id=temprow.id) as s ) as m
      where not exists (select * from inagro_top_greydy u where u.inagro_top_id=m.top_id       
      and u.graydy_id= (select id from its_greydy y where y.code= m.greid_code));   

     end loop;
    
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


