    AS $$
declare 
procname varchar(100) :='syncKSK';
packet varchar(100) := 'InfoRg.KSK_Zhiteli';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

