    where (data::json->'table'->>'Subject') = packet and status=1 and id=temprow.id
   on conflict(company_id,premises_id,period) do update set cli_id=excluded.cli_id,contract_id=excluded.contract_id,premises_ksk_id=excluded.premises_ksk_id;

