--
-- Name: synclog(character varying, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synclog(IN proc_name character varying, IN errtxt text)
    LANGUAGE plpgsql
    AS $$
 
begin
insert into its_sync_errlog(procname,err_txt) values(proc_name,errtxt);
commit;
end;
  
$$;


