-- Name: syncprojects(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncprojects()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncProjects';
packet varchar(100) := 'Cat.Proekty';
temprow record;
begin 
update its_kafkalog set status = 1 where status is null and  (data::json->'table'->>'Subject') = packet;	

for temprow in select * from its_kafkalog where status =1 and  (data::json->'table'->>'Subject') = packet order by id loop 
 INSERT INTO projects(code,title,code_1c,is_delete,is_folder)
    select distinct
    (data::json)->'value'->'Ssylka'->>'ID' as code,
    (data::json)->'value'->'Ssylka'->>'View' as title,
    (data::json)->'value'->>'Kod' as code_1c,
    (case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
    (case when (data::json)->'value'->>'EtoGruppa'= 'true' then 1 else 0 end)  as is_folder
     from its_kafkalog
    where (data::json)->'table'->>'Subject' = packet
    and status = 1 and id=temprow.id
    ON CONFLICT (code) DO UPDATE SET title = EXCLUDED.title,code_1c = EXCLUDED.code_1c,is_delete = EXCLUDED.is_delete,is_folder = excluded.is_folder;

    
   end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

end;
$$;


