--
-- Name: syncsotrudniki(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncsotrudniki()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncSotrudniki';
packet varchar(100) := 'Cat.Sotrudniki';
temprow record;
user_id integer;
begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop	
	
begin 

select count(1) into user_id from users where code=temprow.data->'value'->'FizicheskoeLitso'->>'ID';

if user_id = 0 then 

update its_kafkalog set status = 3,last_error = 'no user id in users table'  where id= temprow.id;

else

  insert into users_companies(code,code_hr,is_delete,is_arch,users_id,company_id)
    select   distinct
    (s.data::json)->'value'->'Ssylka'->>'ID' as code, 
    (s.data::json)->'value'->>'Kod' as kod ,
    (case when (s.data::json)->'value'->>'PometkaUdaleniya' = 'true' then 1 else 0 end) as is_delete,
    (case when (s.data::json)->'value'->>'VArkhive' = 'true' then 1 else 0 end) as is_arch,
    u.id as user_id  ,
    (select id from companies where code =(s.data::json)->'value'->'GolovnayaOrganizatsiya'->>'ID' ) as company_id
    from its_kafkalog s
    join users u on u.code=(s.data::json)->'value'->'FizicheskoeLitso'->>'ID'
    where (s.data::json->'table'->>'Subject') = packet --and s.created_at >current_date --
    and s.status=1  and s.id=temprow.id
    on conflict (code) do update set is_delete=EXCLUDED.is_delete,is_arch=EXCLUDED.is_arch,company_id=EXCLUDED.company_id ;
   
   
update users_companies u
set its_greydy_id = p.greydy_id,
position_level_id = p.level_id,
staff_type_id = (select id from staff_type where code= p.type),
task_staff_id=(select id from task_staff where company_id=u.company_id)
from hr_position p  where p.id= u.hr_position_id and u.code in (select (s.data::json)->'value'->'Ssylka'->>'ID'  from its_kafkalog s where (s.data::json->'table'->>'Subject') = packet  and s.status=1 and s.id=temprow.id );
   

end if;

exception when others then
 update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

end;


end loop;

begin
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;
insert into its_kafkalog_hst(data,old_id,old_at,status)
select data,id,created_at,status from its_kafkalog  where (status = 3 or status = 5)  and  (data::json->'table'->>'Subject') = packet;
delete from its_kafkalog  where (status = 3  or status = 5)  and  (data::json->'table'->>'Subject') = packet;
end;

end;
$$;


