--
-- Name: syncstaff(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncstaff()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncStaff';
packet varchar(100) := 'Cat.OtvetstvennyeLitsaOrganizatsiy';

temprow  record;
begin 
update its_kafkalog set status = 1 where status is null and  (data::json->'table'->>'Subject') = packet ;
    
   
for temprow in select (data::json)->'value'->'Vladelets'->>'ID' as code,max(to_date(data->'value'->>'DataNachala','yyyy-mm-dd')) as max_date
from its_kafkalog s 
where (data::json->'table'->>'Subject')='Cat.OtvetstvennyeLitsaOrganizatsiy' and status=1
and (to_date((data::json)->'value'->>'DataOkonchaniya','yyyy-mm-dd') > current_date  or  (data::json)->'value'->>'DataOkonchaniya' is null or  (data::json)->'value'->>'DataOkonchaniya' ='null')
and (data::json)->'value'->'OtvetstvennoeLitso' ->>'ID' ='Руководитель'
and (data::json)->'value'->'FizicheskoeLitso'->>'ID'  not in ('5dde68bc-ee5a-11e8-80d2-001dd8b71c90')
group by (data::json)->'value'->'Vladelets'->>'ID' loop

insert into task_staff (code,title,user_id,company_id,users_companies_id,staff_position_id,job_title)
select * from (
select  distinct (data::json)->'value'->'Vladelets'->>'ID'  as code, 
 (data::json)->'value'->>'Naimenovanie' as title,
(select id from  users u where   u.code = (data::json)->'value'->'FizicheskoeLitso'->>'ID' ) as user_id,
(select id from companies  where code= (data::json)->'value'->'Vladelets'->>'ID' ) as company_id,
(select id from users_companies where code = (data::json)->'value'->'BI_Sotrudnik'->>'ID') as users_companies_id,
(select id from staff_position where code = (data::json)->'value'->'DolzhnostSsylka'->>'ID') as staff_position_id,
(data::json)->'value'->>'Dolzhnost' as job_title
from its_kafkalog s 
where (data::json->'table'->>'Subject')='Cat.OtvetstvennyeLitsaOrganizatsiy' and status=1
and (to_date((data::json)->'value'->>'DataOkonchaniya','yyyy-mm-dd') > current_date  or  (data::json)->'value'->>'DataOkonchaniya' is null  or  (data::json)->'value'->>'DataOkonchaniya'= 'null')
and (data::json)->'value'->'OtvetstvennoeLitso' ->>'ID' ='Руководитель'
--and ((data::json)->'value'->>'PravoPodpisiPoDoverennosti')='false'
--and (select id from  users u where   u.code = (data::json)->'value'->'FizicheskoeLitso'->>'ID' ) is not null

and (data::json)->'value'->'FizicheskoeLitso'->>'ID'  not in ('5dde68bc-ee5a-11e8-80d2-001dd8b71c90')
and (data::json)->'value'->'Vladelets'->>'ID' =temprow.code and to_date((data::json)->'value'->>'DataNachala','yyyy-mm-dd')=temprow.max_date ) s 
where s.users_companies_id is not null
on conflict(code) do update set user_id=EXCLUDED.user_id , company_id=EXCLUDED.company_id ,users_companies_id=EXCLUDED.users_companies_id ,staff_position_id=EXCLUDED.staff_position_id ,job_title=EXCLUDED.job_title;
    
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet
             and (data::json)->'value'->'Vladelets'->>'ID' =temprow.code;
            
       
   end loop;
           
exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


