--
-- Name: synctd(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synctd()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncTD';
packet varchar(100) := 'Doc.PriemNaRabotu';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop


   
   insert into users_companies(code,code_hr,is_delete,users_id,company_id,contract_date,contract_number,adm_header_id,func_header_id,work_type_id,project_id,deps_id,staff_position_id,hr_position_id)
    select   distinct
    (s.data::json)->'value'->'Sotrudnik'->>'ID' as code, 
    (s.data::json)->'value'->>'Nomer' as code_hr ,
    (case when (s.data::json)->'value'->>'PometkaUdaleniya' = 'true' then 1 else 0 end) as is_delete,

    (select u.id from  users u where  u.code=(s.data::json)->'value'->'FizicheskoeLitso'->>'ID') as user_id  ,
    (select c.id from companies c where code =(s.data::json)->'value'->'Organizatsiya'->>'ID' ) as company_id,
    (s.data::json->'value'->>'TrudovoyDogovorData')::date as contract_date,
    (s.data::json->'value'->>'TrudovoyDogovorNomer') as contract_number,
    (select u.id from users u where code= s.data->'value'->'INAGRO_AdministrativnyyRukovoditel'->>'ID') as adm_header_id,
    (select u.id from users u where code= s.data->'value'->'INAGRO_FunktsionalnyyRukovoditel'->>'ID') as func_header_id,
    (select w.id from work_type w where code=s.data->'value'->'VidZanyatosti'->>'ID') as work_type_id,
    (select p.id from projects p where code= s.data->'value'->'INAGRO_ProektOrganizatsii'->>'ID') as project_id,
    (select d.id from deps d where code= s.data->'value'->'Podrazdelenie'->>'ID') as deps_id,
    (select d.id from staff_position d where code= s.data->'value'->'DolzhnostPoShtatnomuRaspisaniyu'->>'ID') as staff_position_id,
     (select d.id from hr_position d where code= s.data->'value'->'Dolzhnost'->>'ID') as hr_position_id
    
    from its_kafkalog s
    
    where (s.data::json->'table'->>'Subject') = packet --and s.created_at >current_date --
    and s.status=1  and s.id=temprow.id
    on conflict (code) do update set code_hr=EXCLUDED.code_hr,is_delete=EXCLUDED.is_delete,company_id=EXCLUDED.company_id,users_id=EXCLUDED.users_id ,contract_date=EXCLUDED.contract_date ,contract_number=EXCLUDED.contract_number,
   adm_header_id=EXCLUDED.adm_header_id ,func_header_id=EXCLUDED.func_header_id,work_type_id=EXCLUDED.work_type_id ,project_id=EXCLUDED.project_id,deps_id=EXCLUDED.deps_id, staff_position_id=EXCLUDED.staff_position_id,hr_position_id=EXCLUDED.hr_position_id;
   
   
update users_companies u
set its_greydy_id = p.greydy_id,
position_level_id = p.level_id,
staff_type_id = (select id from staff_type where code= p.type),
task_staff_id=(select id from task_staff where company_id=u.company_id)
from hr_position p  where p.id= u.hr_position_id and u.code in (select (s.data::json)->'value'->'Sotrudnik'->>'ID'  from its_kafkalog s where (s.data::json->'table'->>'Subject') = packet  and s.status=1 and s.id=temprow.id );
   
   
   
end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


