--

CREATE PROCEDURE public.synctdspisok()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='synctdSpisok';
packet varchar(100) := 'Doc.PriemNaRabotuSpiskom';
temprow record;
temprow3 record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow3 in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop

	for temprow in select  distinct 
    (temprow2.data::json)->'Sotrudnik'->>'ID' as code, 
   -- (temprow2.data::json)->>'Nomer' as code_hr ,
    (case when (temprow2.parent::json)->'value'->>'PometkaUdaleniya' = 'true' then 1 else 0 end) as is_delete,(temprow2.parent::json)->'value'->>'PometkaUdaleniya',
	
    (select u.id from  users u where  u.code=(temprow2.data::json)->'FizicheskoeLitso'->>'ID') as users_id  ,(temprow2.data::json)->'FizicheskoeLitso'->>'ID',
    (select c.id from companies c where code =(temprow2.parent::json)->'value'->'Organizatsiya'->>'ID' ) as company_id,
    (temprow2.data::json->>'TrudovoyDogovorData')::date as contract_date,
    (temprow2.data::json->>'TrudovoyDogovorNomer') as contract_number,
    (select u.id from users u where code= temprow2.data->'INAGRO_AdministrativnyyRukovoditel'->>'ID') as adm_header_id,
    (select u.id from users u where code= temprow2.data->'INAGRO_FunktsionalnyyRukovoditel'->>'ID') as func_header_id,
    (select w.id from work_type w where code=temprow2.data->'VidZanyatosti'->>'ID') as work_type_id,
    (select p.id from projects p where code= temprow2.parent->'value'->'INAGRO_ProektOrganizatsii'->>'ID') as project_id,
    (select d.id from deps d where code= temprow2.data->'Podrazdelenie'->>'ID') as deps_id,
    Upsert(temprow2.data->'DolzhnostPoShtatnomuRaspisaniyu'->>'View',temprow2.data->'DolzhnostPoShtatnomuRaspisaniyu'->>'ID','staff_position') as staff_position_id,
    Upsert(temprow2.data->'Dolzhnost'->>'View',temprow2.data->'Dolzhnost'->>'ID','hr_position')  as hr_position_id,
 
     (select id from its_greydy y where y.code=data->'Greyd'->>'ID') as its_greydy_id from  (select jsonb_array_elements(data->'value'->'Sotrudniki') as data,data as parent from its_kafkalog   where id=temprow3.id) temprow2
	where (select u.id from  users u where  u.code=(temprow2.data::json)->'FizicheskoeLitso'->>'ID') is not null loop 
   
   insert into users_companies(code,is_delete,is_arch,users_id,company_id,contract_date,contract_number,adm_header_id,func_header_id,work_type_id,project_id,deps_id,staff_position_id,hr_position_id,its_greydy_id)
    
   select   distinct
    temprow.code as code,
--    temprow.code_hr as code_hr,
    temprow.is_delete as is_delete,
    coalesce(temprow.is_delete,0) as is_arch ,
    temprow.users_id as users_id,
    temprow.company_id as company_id,
    temprow.contract_date as contract_date,
    temprow.contract_number as contract_number,
    temprow.adm_header_id as adm_header_id,
    temprow.func_header_id as func_header_id,
    temprow.work_type_id as work_type_id,
    temprow.project_id as project_id,
    temprow.deps_id as deps_id,
    temprow.staff_position_id as staff_position_id,
    temprow.hr_position_id as hr_position_id,
    temprow.its_greydy_id
    on conflict (code) do update set is_delete=EXCLUDED.is_delete,is_arch=EXCLUDED.is_arch,company_id=EXCLUDED.company_id,users_id=EXCLUDED.users_id ,contract_date=EXCLUDED.contract_date ,contract_number=EXCLUDED.contract_number,
   adm_header_id=EXCLUDED.adm_header_id ,func_header_id=EXCLUDED.func_header_id,work_type_id=EXCLUDED.work_type_id ,project_id=EXCLUDED.project_id,deps_id=EXCLUDED.deps_id, staff_position_id=EXCLUDED.staff_position_id,hr_position_id=EXCLUDED.hr_position_id,its_greydy_id=EXCLUDED.its_greydy_id;
   
   
	update users_companies u set 
	position_level_id = p.level_id,
	staff_type_id = (select id from staff_type where code= p.type),
	task_staff_id=(select id from task_staff where company_id=u.company_id)
	from hr_position p  where p.id= u.hr_position_id and u.code =temprow.code;
	   
	end loop;
	   
end loop;
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;

insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow3.id;
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: synctrip(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.synctrip()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='synctrip';
packet varchar(100) := 'InfoRg.INAGRO_NormyKomandirovochnykh';
temprow record;
begin 
update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from 	its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop

begin
insert into its_norm_trip(its_dayallow_type_id,title,period,currency_id,inargo_holding_id,trip_locality_id,staff_level_id,summa,stavka_mrp)
select distinct 
Upsert( (data::json)->'value'->'Vid'->>'View' , (data::json)->'value'->'Vid'->>'ID','its_dayallow_type'  ) as its_dayallow_type_id ,
(data::json)->'value'->'Vid'->>'View' as title,
to_date((data->>'Period'),'yyyy-mm-dd') as period,
Upsert((data::json)->'value'->'Valyuta'->>'View',(data::json)->'value'->'Valyuta'->>'ID','its_currency') as currency_id,
Upsert((data::json)->'value'->'Kholding'->>'View',(data::json)->'value'->'Kholding'->>'ID','holding') as inargo_holding_id,
Upsert((data::json)->'value'->'Territoriya'->>'View',(data::json)->'value'->'Territoriya'->>'ID' ,'its_local_trip' ) as trip_locality_id,
Upsert((data::json)->'value'->'UrovenDolzhnosti'->>'View',(data::json)->'value'->'UrovenDolzhnosti'->>'ID','hr_position_level' )  as staff_level_id,
coalesce((data::json)->'value'->>'Summa','0')::bigint as summa,
coalesce((data::json)->'value'->>'StavkaMRP','0')::bigint as stavka_mrp

from its_kafkalog 
    where (data::json->'table'->>'Subject') = packet and status=1 and id=temprow.id
   on conflict(its_dayallow_type_id,currency_id,inargo_holding_id,trip_locality_id,staff_level_id) do update set title=excluded.title,summa=excluded.summa,period=excluded.period,stavka_mrp=excluded.stavka_mrp;

  
 exception when others then

 raise info '%',sqlerrm||' '||temprow.id;
  end ;
 end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


-- exception when others then
-- call syncLog(procname,sqlerrm);
-- raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: syncuchastkion(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncuchastkion()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='UchastkiObektovNedvizhimosti';
packet varchar(100) := 'Cat.UchastkiObektovNedvizhimosti';
temprow record;
BEGIN

--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

for temprow in select * from its_kafkalog where status = 1  and  (data::json->'table'->>'Subject') = packet order by id loop

	insert into its_uchastkion(code,title,code_1c,project)
     select 
     (data::json)->'value'->'Ssylka'->>'ID'  as code ,
     (data::json)->'value'->'Ssylka'->>'View'  as title,
     (data::json)->'value'->>'Kod' as code_1c,
     (select id from projects where code=(data::json)->'value'->'Proekt'->>'ID') as project
     from its_kafkalog  s  
     where (data::json->'table'->>'Subject') = packet  and status=1 and s.id=temprow.id
     on conflict(code) do update set title = EXCLUDED.title,code_1c = EXCLUDED.code_1c,project = EXCLUDED.project;
     
    INSERT INTO its_out_exc_partners(code,title,ref_type,status)
    select distinct
    (data::json)->'value'->'Ssylka'->>'ID' as code,
    (data::json)->'value'->'Ssylka'->>'View' as title,
    'its_uchastkion' as ref_type,
    1 as status
     from its_kafkalog s
    where (data::json)->'table'->>'Subject' = packet
    and status = 1 and s.id=temprow.id
    ON CONFLICT (code) DO UPDATE SET title = EXCLUDED.title,status = EXCLUDED.status;
      
end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


--exception when others then
--call syncLog(procname,sqlerrm);
--raise info '%',sqlerrm||' '||procname;

	END;
$$;


--
-- Name: syncunit(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncunit()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncUnit';
packet varchar(100) := 'Cat.KlassifikatorEdinitsIzmereniya';

begin 


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;


insert into its_unit(code,title,is_delete,kod,full_name)
select distinct 
(data::json)->'value'->'Ssylka'->>'ID'  as code ,
(data::json)->'value'->'Ssylka'->>'View' as title,
(case when (data::json)->'value'->>'PometkaUdaleniya'= 'true' then 1 else 0 end)  as is_delete,
(data::json)->'value'->>'Kod' as kod,
(data::json)->'value'->>'NaimenovaniePolnoe' as full_name
from its_kafkalog 
    where (data::json->'table'->>'Subject') = packet and status=1
   on conflict(code) do update set title=excluded.title,is_delete=excluded.is_delete,kod=excluded.kod,full_name=excluded.full_name;

  
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: syncusercomp_func(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.syncusercomp_func() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare 
temprow record;
BEGIN
--update users u set company_id =(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where uc.work_type_id =2 and coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ); 
--update users u set company_id =(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where  coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ) where company_id is null; 


for temprow in select id,(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where uc.work_type_id =2 and coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ) as company_id  from users u loop

update users u set company_id =temprow.company_id
where u.id=temprow.id;
commit;
end loop;




for temprow in select id,(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where  coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ) as company_id from users u  where u.company_id is null loop

update users u set company_id =temprow.company_id
where u.id=temprow.id;
commit;
end loop;






for temprow in select * from users_companies where is_arch ='0'
and hr_position_id is null 
and staff_position_id is null loop 

update users_companies 
set is_arch='1'
where id=temprow.id;
commit;

end loop;

return "ok";

END;
$$;


