--update users u set company_id =(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where  coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ) where company_id is null; 


for temprow in select id,(select company_id from users_companies s where s.id=(select min(id) from users_companies uc where uc.work_type_id =2 and coalesce(is_delete,0) =0 and coalesce(is_arch,0)=0 and uc.users_id =u.id and uc.company_id is not null )  ) as company_id  from users u loop

