--
-- Name: syncusers(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncusers()
    LANGUAGE plpgsql
    AS $$
declare
procname varchar(100) :='syncUsers';
packet varchar(100) := 'Cat.StepeniZnaniyaYazyka';
temprow record;
step varchar;
begin


update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') in ( 'Cat.FizicheskieLitsa' ,'Cat.ФизическиеЛица' );


for temprow in 	select  id, (data)->'value'->'Ssylka'->>'ID'  as code,
    (data)->'value'->'Ssylka'->>'View'  as title ,
    (select id from sex where code=(data)->'value'->'Pol'->>'ID')  as sex_fl,
    (data)->'value'->>'Kod'  as code_hr,
     (data)->'value'->>'FIO'  as fio,
     (data)->'value'->>'INN'  as iin,
     (data)->'value'->>'BI_KorporativnyyEmail'  as email,
    case when data->'value'->>'BI_AkkauntAD'='' then uuid_generate_v4()::varchar  else
    data->'value'->>'BI_AkkauntAD' end  as login,
    to_date((data)->'value'->>'DataRozhdeniya','yyyy-mm-dd' ) as bday,
    1 as ldap_id,
    data->'value'->'KontaktnayaInformatsiya' as cont
    from its_kafkalog

	where   (data->'table'->>'Subject')  in ( 'Cat.FizicheskieLitsa' ,'Cat.ФизическиеЛица' ) and status=1 order by id loop

	step='1';

	begin
	insert into users(code,title,iin,sex_fl,bday,login,ldap_id,email,code_hr,short_name)
    select temprow.code as code,temprow.title as title,temprow.iin as iin,(temprow.sex_fl::int) as sex_fl,temprow.bday as bday,temprow.login as login,temprow.ldap_id as ldap_id,temprow.email as email,temprow.code_hr as code_hr,
    coalesce(trim((regexp_split_to_array(temprow.title, ' '))[1]|| ' '|| substring((regexp_split_to_array(temprow.title, ' '))[2],1,1)||'. '||
      (case when (regexp_split_to_array(temprow.title, ' '))[3] is not null then
     	substring((regexp_split_to_array(temprow.title, ' '))[3],1,1)||'.'
      	else ' ' end)),temprow.title ) as short_name
    on CONFLICT(code) do update set title=EXCLUDED.title,iin=EXCLUDED.iin,sex_fl=EXCLUDED.sex_fl,bday=EXCLUDED.bday,email=EXCLUDED.email,code_hr=EXCLUDED.code_hr,short_name =EXCLUDED.short_name,login =EXCLUDED.login;
	step='2';
   	insert into cont_groups(code,title)
	select jsonb_array_elements(temprow.cont)->'Tip'->>'ID' as code,jsonb_array_elements(temprow.cont)->'Tip'->>'View' as title
    on conflict(code) do nothing;
   step='3';
   	insert into cont_types(code,title,group_id)
	select s.*,(select id from  cont_groups where code=s.code) as group_id from (select jsonb_array_elements(temprow.cont)->'Vid'->>'ID' as code,jsonb_array_elements(temprow.cont)->'Vid'->>'View' as title )
	s

    on conflict(code) do nothing;
   step='4';
     insert into user_cont (nomer_telefona,view_txt,nomer_telefona_bk,type_id,users_id,xml_value)
      select * from (select s.nomer_telefona,s.view_txt,s.nomer_telefona_bk,
     	(select id from cont_types where code=s.typ_id) as type_id,s.users_id,s.xml_value
     from
     (select  jsonb_array_elements(temprow.cont)->>'NomerTelefona' as nomer_telefona,
     jsonb_array_elements(temprow.cont)->>'Predstavlenie' as view_txt,
     jsonb_array_elements(temprow.cont)->>'NomerTelefonaBezKodov' as nomer_telefona_bk,
     jsonb_array_elements(temprow.cont)->'Vid'->>'ID' as typ_id,
     (select id from users where code=temprow.code) as users_id,
     jsonb_array_elements(temprow.cont)->>'ZnacheniyaPoley' as xml_value) s ) d
     where not exists (select 1 from user_cont c where c.view_txt=d.view_txt and c.users_id=d.users_id)
     and d.users_id is  not null and d.type_id in (select id from cont_types
     where code in  ('203b949d-871c-11e7-80c4-00155da78904','6ec35f4a-b8ee-11e7-aa90-5cb9019dbd39' ,'fb9a6b7e-b95d-11e7-aa90-5cb9019dbd39') );
step='5';

     insert into user_roles(user_id,role_id)
     select id ,(select id from roles where code='its_user') as role_id  from users u where code=temprow.code
     and not exists(select 1 from user_roles r where r.user_id=u.id and r.role_id= (select id from roles where code='its_user'));




    exception when others then
  	--call syncLog(procname,temprow.id::text||' '||sqlerrm);
    update its_kafkalog set last_error =substring(sqlerrm,1,250),status = 3 where id=temprow.id;
	--raise info '%',sqlerrm||' '||procname||' '||step||' log_id='||temprow.id;
    end;


	end loop;

update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject')  in ( 'Cat.FizicheskieLitsa' ,'Cat.ФизическиеЛица' );


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where (status = 2 or status = 3)  and  (data::json->'table'->>'Subject')  in ( 'Cat.FizicheskieLitsa' ,'Cat.ФизическиеЛица' );
delete from its_kafkalog  where (status = 2 or status = 3) and  (data::json->'table'->>'Subject')  in ( 'Cat.FizicheskieLitsa' ,'Cat.ФизическиеЛица' );


end;
$$;


