-- Name: syncuvolnenie(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncuvolnenie()
    LANGUAGE plpgsql
    AS $$
declare 
procname varchar(100) :='syncUvolnenie';
packet varchar(100) := 'Doc.Uvolnenie';
temprow record;
begin 


--update its_kafkalog set status = 1 where status is null  and  (data::json->'table'->>'Subject') = packet;

update users_companies 
set is_arch ='1',
is_delete ='1'
where code in (select (data)->'value'->'Sotrudnik'->>'ID'  from its_kafkalog where status =1 and (data::json->'table'->>'Subject') = packet);
	
update its_kafkalog set status = 2 where status = 1  and  (data::json->'table'->>'Subject') = packet;


insert into its_kafkalog_hst(data,old_id,old_at)
select data,id,created_at from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;

delete from its_kafkalog  where status = 2  and  (data::json->'table'->>'Subject') = packet;


exception when others then
call syncLog(procname,sqlerrm);
raise info '%',sqlerrm||' '||procname;

end;
$$;


--
-- Name: syncvacancy(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.syncvacancy()
    LANGUAGE plpgsql
    AS $$
declare 
packet varchar(100) := 'Cat.Vakansii';
temprow record;
hr_position_id bigint;
companies_id bigint;
its_city_id bigint;
vacancii_id bigint;

	begin
		-- vtoroi start
		--update its_kafkalog set status = 1 where status is null  and (data::json->'table'->>'Subject')  = v_packet  and (data::json->'value'->'Vladelets'->>'Type') = type;
		for temprow in select * from its_kafkalog where (data::json->'table'->>'Subject') = packet and status = 1
		
		order by id
		
		loop
		
		hr_position_id := upsert_by_code('hr_position', jsonb_build_object
			(
				'code', temprow.data->'value'->'Dolzhnost'->>'ID',
				'title', temprow.data->'value'->'Dolzhnost'->>'View'
			) 
		);
		
		companies_id := upsert_by_code('companies', jsonb_build_object 
			(
				'code', temprow.data->'value'->'BI_Organizatsiya'->>'ID',
