--
-- Name: to_text(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.to_text(numeric) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
SELECT CASE WHEN $1<1 THEN NULL
              WHEN $1=1 THEN 'ONE'
              WHEN $1=2 THEN 'TWO'
              WHEN $1=3 THEN 'THREE'
              WHEN $1=4 THEN 'FOUR'
              WHEN $1=5 THEN 'FIVE'
              WHEN $1=6 THEN 'SIX'
              WHEN $1=7 THEN 'SEVEN'
              WHEN $1=8 THEN 'EIGHT'
              WHEN $1=9 THEN 'NINE'
              WHEN $1=10 THEN 'TEN'
              WHEN $1=11 THEN 'ELEVEN'
              WHEN $1=12 THEN 'TWELVE'
              WHEN $1=13 THEN 'THIRTEEN'
              WHEN $1=14 THEN 'FOURTEEN'
              WHEN $1=15 THEN 'FIFTEEN'
              WHEN $1=16 THEN 'SIXTEEN'
              WHEN $1=17 THEN 'SEVENTEEN'
              WHEN $1=18 THEN 'EIGHTEEN'
              WHEN $1=19 THEN 'NINETEEN'
              WHEN $1<100 THEN CASE
                 WHEN $1/10=2 THEN 'TWENTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=3 THEN 'THIRTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=4 THEN 'FOURTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=5 THEN 'FIFTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=6 THEN 'SIXTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=7 THEN 'SEVENTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=8 THEN 'EIGHTY' || COALESCE(' ' || to_text($1%10), '')
                 WHEN $1/10=9 THEN 'NINETY' || COALESCE(' ' || to_text($1%10), '')
              END
              WHEN $1<1000
                 THEN to_text($1/100) || ' HUNDRED' ||
                      COALESCE(' AND ' || to_text($1%100), '')
              WHEN $1<1000000
                 THEN to_text($1/1000) || ' THOUSAND' ||
                      CASE WHEN $1%1000 < 100
                         THEN COALESCE(' AND ' || to_text($1%1000), '')
                         ELSE COALESCE(' ' || to_text($1%1000), '')
                      END
              WHEN $1<1000000000
                 THEN to_text($1/1000000) || ' MILLION' ||
                      CASE WHEN $1%1000000 < 100
                         THEN COALESCE(' AND ' || to_text($1%1000000), '')
                         ELSE COALESCE(' ' || to_text($1%1000000), '')
                      END
              ELSE NULL
         END
$_$;


--
-- Name: updateproblemcontr(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.updateproblemcontr()
    LANGUAGE plpgsql
    AS $$
declare
packet varchar(100) := 'Cat.Partners';
packet2 varchar(100) := 'Cat.Kontragenty';
temprow record;
begin
for temprow in select * from 	its_kafkalog_hst where   (data::json->'table'->>'Subject') in (packet,packet2) order by id loop
update its_cli
    set problemnyy_kontragent = (case when (data::json)->'value'->>'ProblemnyyKontragent'='true' then 1 else 0 end )
from its_kafkalog_hst
    where (data::json->'table'->>'Subject') in (packet,packet2)  and code = (data::json)->'value'->'Ssylka'->>'ID' ;
end loop;
end;
$$;


--
-- Name: upsert(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert(title character varying, code character varying, entity_code character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
cnt integer;
sql_txt varchar;
id bigint;
begin 
	
sql_txt:=' select count(1) from '|| entity_code ||' where  code='''|| code ||'''' ;		

execute  sql_txt into cnt;

if cnt=0 then 

sql_txt:=' insert into '|| entity_code ||'(code,title) values('''||code||''','''||title||''') RETURNING id';
execute  sql_txt into id; 
else 
sql_txt:=' select id from '|| entity_code ||' where  code='''|| code||''' limit 1' ;	
execute  sql_txt into id; 

end if;

return id;
end;
$$;


--
-- Name: upsert_by_code(character varying, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_by_code(entity_code character varying, data jsonb) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare 
cnt integer;
sql_txt varchar;
id bigint;
temprow record;

update_sql_add text := '';
insert_sql_add text := '';
insert_sql_add_fields text := '';

v_value text := '';
v_found boolean := false;
v_procname text := 'upsert_by_code';
begin
	

sql_txt:=concat(' select count(1) from ', entity_code ,' where  code=''', ((data::jsonb)->>'code')::text ,'''') ;		

--select json_object_keys ( '{"code":"test2","title":"Привет3"}' )

for temprow in select jsonb_object_keys ( data ) loop

if temprow.jsonb_object_keys <> 'code' and ((data::jsonb)->>temprow.jsonb_object_keys) is not null then
    v_found := true;
    v_value := quote_nullable ( ((data::jsonb)->>temprow.jsonb_object_keys)::text);
	update_sql_add := concat(update_sql_add ,  ',' , temprow.jsonb_object_keys , ' =  ',v_value);
	insert_sql_add_fields := concat(insert_sql_add_fields ,  ',' , temprow.jsonb_object_keys);
	insert_sql_add := concat( insert_sql_add ,  ',  ', v_value);
end if;




end loop;

update_sql_add := Trim(Trim(update_sql_add) ,',');
insert_sql_add_fields := Trim(Trim(insert_sql_add_fields) ,',');
insert_sql_add := Trim(Trim(insert_sql_add) ,',');


if not v_found then 
	--PERFORM  syncLog(v_procname,((data::jsonb)->>'code')::text);
	return null;
end if;


execute  sql_txt into cnt;

if cnt=0 then 

sql_txt:= concat( ' insert into ', entity_code ,'(code, ', insert_sql_add_fields , ') values(''',((data::jsonb)->>'code')::text,''', ' , insert_sql_add , ') RETURNING id');

raise info 'sql text 1 %',sql_txt;
execute  sql_txt into id; 
else 

 


sql_txt:=concat(' select id from ', entity_code ,' where  code=''', ((data::jsonb)->>'code')::text ,''' limit 1') ;	


raise info 'sql text 2 %',sql_txt;

execute  sql_txt into id; 

sql_txt:=concat(' update ', entity_code ,' set ', update_sql_add ,' where code = ''',((data::jsonb)->>'code')::text,''' ');

raise info 'sql text 3 %',sql_txt;
execute  sql_txt ; 

end if;

return id;
end;

$$;


