--
-- Name: dvga_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dvga_activity AS
 SELECT date(created_at) AS created_date,
    department_title,
    user_name AS full_name,
    count(*) AS record_count
   FROM ( SELECT bi.created_at,
            dep.title AS department_title,
            u.title AS user_name
           FROM ((public."i$login_by_sms" bi
             JOIN public.users u ON (((u.login)::text = (bi.login)::text)))
             LEFT JOIN public.its_departments dep ON ((dep.id = u.its_departments_id)))
          WHERE ((bi.created_at >= '2024-11-18 00:00:00+05'::timestamp with time zone) AND ((dep.title)::text ~~ '%ДВГА%'::text))
        UNION ALL
         SELECT bi.created_at,
            dep.title AS department_title,
            u.title AS user_name
           FROM ((public.bp_instances bi
             JOIN public.users u ON ((u.id = bi.created_by)))
             LEFT JOIN public.its_departments dep ON ((dep.id = u.its_departments_id)))
          WHERE ((bi.created_at >= '2024-11-18 00:00:00+05'::timestamp with time zone) AND ((dep.title)::text ~~ '%ДВГА%'::text))) t
  GROUP BY (date(created_at)), department_title, user_name
  ORDER BY (date(created_at)), department_title, user_name;


